script.setup:
// Tone.js plays a generative arpeggio (PolySynth → reverb); its FFT and waveform drive the picture.
// Browsers start audio only after a gesture: click the viewport.
const Tone = await ctx.utils.import("https://esm.sh/tone@15.1.22");
const synth = new Tone.PolySynth(Tone.Synth, { oscillator: { type: "triangle8" }, envelope: { attack: 0.005, decay: 0.25, sustain: 0.15, release: 1.4 } });
const reverb = new Tone.Reverb({ decay: 3.5, wet: 0.35 });
const fft = new Tone.FFT(64), wave = new Tone.Waveform(128);
synth.chain(reverb, Tone.getDestination());
synth.connect(fft); synth.connect(wave);
synth.volume.value = -10;
const chords = [["C4", "E4", "G4", "B4"], ["A3", "C4", "E4", "G4"], ["F3", "A3", "C4", "E4"], ["G3", "B3", "D4", "F4"]];
let step = 0;
const loop = new Tone.Loop((time) => {
  const chord = chords[Math.floor(step / 16) % chords.length];
  const note = Tone.Frequency(chord[[0, 1, 2, 3, 2, 1, 3, 2][step % 8]]).transpose(step % 16 >= 8 ? 12 : 0);
  synth.triggerAttackRelease(note, "16n", time, 0.5 + 0.5 * Math.random());
  Tone.getDraw().schedule(() => { ctx.state.hit = 1; }, time);
  step++;
}, "8n");
const start = async () => {
  if (ctx.state.playing) return;
  await Tone.start();
  loop.start(0);
  Tone.getTransport().start();
  ctx.state.playing = true;
};
window.addEventListener("pointerdown", start);
Object.assign(ctx.state, { Tone, synth, reverb, fft, wave, loop, start, hit: 0, playing: false,
  waveData: new Float32Array(128), fftData: new Float32Array(64),
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor;\nuniform vec2 u_resolution; uniform float u_wave[128]; uniform float u_fft[64]; uniform float u_hit; uniform float u_time;\nuniform vec3 u_color;\nvoid main(){\n  vec2 p = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);\n  float r = length(p), a = atan(p.y, p.x) / 6.2831853 + 0.5;\n  float fi = a * 64.0; int k = int(fi) % 64;\n  float bar = u_fft[k];\n  float wi = a * 127.0; int j = int(wi);\n  float w = mix(u_wave[j], u_wave[min(j + 1, 127)], fract(wi));\n  float ring = 0.22 + 0.06 * w + 0.03 * u_hit;\n  float line = exp(-abs(r - ring) * 220.0);\n  float spikes = step(0.3, r) * step(r, 0.3 + bar * 0.22) * smoothstep(0.5, 0.35, abs(fract(fi) - 0.5));\n  vec3 col = u_color * (line * 1.6 + spikes * 0.7) + vec3(0.9, 0.95, 1.0) * line * 0.4;\n  col += u_color * 0.12 * u_hit * exp(-r * 6.0);\n  outColor = vec4(col + vec3(0.02, 0.02, 0.035), 1.0);\n}") });

script.render:
const s = ctx.state, u = ctx.uniforms;
s.Tone.getTransport().bpm.value = u.u_tempo;
if (s.playing) {
  s.waveData.set(s.wave.getValue());
  const db = s.fft.getValue();
  for (let i = 0; i < 64; i++) s.fftData[i] = Math.max(0, Math.min(1, (db[i] + 100) / 70));
} else {
  // Before the first click: a quiet breathing ring.
  for (let i = 0; i < 128; i++) s.waveData[i] = 0.3 * Math.sin(i / 128 * Math.PI * 6 + ctx.time * 2) * (0.5 + 0.5 * Math.sin(ctx.time));
  for (let i = 0; i < 64; i++) s.fftData[i] = 0.25 * Math.pow(0.5 + 0.5 * Math.sin(i * 0.9 + ctx.time * 1.5), 3);
}
s.hit *= Math.exp(-ctx.dt * 6);
ctx.publish("audio", s.playing ? "playing" : "click the viewport to start");
ctx.gl.useProgram(s.p);
ctx.utils.drawFullscreen(s.p, { u_wave: s.waveData, u_fft: s.fftData, u_hit: s.hit });

script.cleanup:
const s = ctx.state;
window.removeEventListener("pointerdown", s.start);
s.Tone?.getTransport().stop(); s.Tone?.getTransport().cancel();
for (const node of [s.loop, s.synth, s.reverb, s.fft, s.wave]) node?.dispose();
